import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';

const root = process.cwd();
const articlesDirectory = path.join(root, 'content/articles');
const outputDirectory = path.join(root, 'out');

const slugs = fs.readdirSync(articlesDirectory)
  .filter((file) => file.endsWith('.md'))
  .filter((file) => matter(fs.readFileSync(path.join(articlesDirectory, file), 'utf8')).data.category === 'Alternatives')
  .map((file) => file.replace(/\.md$/, '').replace(/^\d{4}-\d{2}-\d{2}-/, ''))
  .sort();

const lines = [
  '# Generated by scripts/generate-hosting-redirects.mjs.',
  '# Keep legacy Alternatives URLs as permanent redirects to their root-level canonical URLs.',
  ...slugs.map((slug) => `RedirectMatch 301 "^/articles/${slug}/?$" "/${slug}/"`),
  '',
];

fs.mkdirSync(outputDirectory, { recursive: true });
fs.writeFileSync(path.join(outputDirectory, '.htaccess'), lines.join('\n'));
console.log(`Generated ${slugs.length} permanent Alternatives redirects.`);
